// Title: Convert relative hyperlink URLs to absolute URLs in HTML generated by Aspose.Cells using C#
// Common Searches: C# code to make Aspose.Cells exported HTML links absolute | convert relative href to full URL after saving workbook as HTML with Aspose.Cells | regex replace href attribute in Aspose.Cells generated HTML C# | add base URL to hyperlinks in HTML output from Aspose.Cells workbook | Aspose.Cells HTML export change relative hyperlinks to absolute paths C#
// Tags: Aspose.Cells Hyperlinks.Add absolute conversion | C# Regex href attribute replacement | HTML export link base URL injection | transform relative hyperlinks to absolute in saved HTML | post-process Aspose.Cells HTML output links

using System;
using System.IO;
using System.Text.RegularExpressions;
using Aspose.Cells;

// The example creates a workbook, adds a relative hyperlink to a cell, saves the workbook as HTML, reads the generated HTML, and uses a regular expression to prepend a specified base URL to any href attribute that does not already start with http:// or https://, then writes the modified HTML to a new file.
class HyperlinkAbsoluteUrlExample
{
    static void Main()
    {
        // Create a new workbook and get the first worksheet
        Workbook workbook = new Workbook();
        Worksheet sheet = workbook.Worksheets[0];

        // Add some sample data
        sheet.Cells["A1"].PutValue("Click here");
        // Add a relative hyperlink to cell A1
        sheet.Hyperlinks.Add(0, 0, 1, 1, "relative/path/page.html");

        // Save the workbook as HTML
        string htmlPath = "output.html";
        workbook.Save(htmlPath, SaveFormat.Html);

        // Read the generated HTML into a string
        string htmlContent = File.ReadAllText(htmlPath);

        // Define the base URL to convert relative links to absolute ones
        string baseUrl = "https://example.com/";

        // Replace all href attributes that do NOT start with http:// or https://
        // This regex finds href="some/relative/path"
        string pattern = @"href\s*=\s*""(?!(?:http|https)://)([^""]*)""";
        string replacedHtml = Regex.Replace(htmlContent, pattern,
            m => $"href=\"{baseUrl}{m.Groups[1].Value}\"",
            RegexOptions.IgnoreCase);

        // Write the modified HTML back to the file (or a new file)
        string finalHtmlPath = "output_absolute.html";
        File.WriteAllText(finalHtmlPath, replacedHtml);
    }
}
